def class_s_values(max_active, exps=(-2, -1, 1, 2)):
    vals = set()
    for k in range(1, max_active + 1):
        for combo in itertools.combinations(I_S, k):
            for a in itertools.product(exps, repeat=k):
                v = 1.0
                for n, e in zip(combo, a):
                    v *= n ** e
                if LO <= v <= HI:
                    vals.add(v)

def child_count_types(face_type: CountFace) -> List[CountFace]:
    x, y, z = sorted_counts(face_type)
    return [sorted_counts((0, y + 1, z + 1)),
            sorted_counts((0, x + 1, z + 1)),
            sorted_counts((0, x + 1, y + 1))]
